#pragma once

// DeviceCMYK without a press profile at hand: sRGB colours sampled from SWOP2006_Coated3v2 (ADR 0006) on a
// grid, generated by scripts/gen_cmyk_table.py, interpolated by cmyk_to_rgb (color_space.cpp).

#include <array>
#include <cstdint>

namespace capriole::content::detail {

inline constexpr int kCmykGrid = 9;  // points per ink
extern const std::array<std::uint8_t, static_cast<std::size_t>(kCmykGrid* kCmykGrid* kCmykGrid* kCmykGrid) * 3> kCmykTable;

}  // namespace capriole::content::detail
